<script setup lang="ts">
import { benefitText } from '@/shared/i18n'
import {computed,ref,watch} from 'vue'
import {Search,Download,ChevronLeft,ChevronRight,ArrowUpRight,Rows3,Table2,X} from 'lucide-vue-next'
import {data,latin,num,colors,saveCSV,type Registry} from './data'
import { byRegistry, searchKey } from './svod'
const emit=defineEmits<{open:[Registry]}>()
const query=ref(''),agency=ref(''),type=ref(''),field=ref(''),cohort=ref(''),page=ref(1),matrix=ref(false),matrixBy=ref('field'),matrixGroup=ref('agency')
const linkage = ref('')
const active=computed(()=>!!(query.value||agency.value||type.value||field.value||cohort.value||linkage.value))
const rows=computed(()=>data.registry.filter(x=>(!linkage.value || byRegistry.has(x.id) === (linkage.value === 'linked')) && (!query.value||searchKey(x.id+' '+x.n+' '+x.b+' '+x.o).includes(searchKey(query.value)))&&(agency.value===''||x.oi===+agency.value)&&(type.value===''||x.ti===+type.value)&&(field.value===''||x.fi===+field.value)&&(cohort.value===''||x.ci===+cohort.value)))
watch([query,agency,type,field,cohort,linkage],()=>page.value=1)
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/20)))
const dimensions=computed(()=>[{title:'Chora turlari',names:data.types,values:active.value?data.types.map((_,i)=>rows.value.filter(r=>r.ti===i).length):data.typeTotals,selected:type.value,key:'type'},{title:'Yo‘nalishlar',names:data.fields,values:active.value?data.fields.map((_,i)=>rows.value.filter(r=>r.fi===i).length):data.fieldTotals,selected:field.value,key:'field'},{title:'Aholi toifalari',names:data.cohorts,values:active.value?data.cohorts.map((_,i)=>rows.value.filter(r=>r.ci===i).length):data.cohortTotals.map(x=>x.v[0]??0),selected:cohort.value,key:'cohort'}])
const matrixRows=computed(()=>data.agencies.map((a,i)=>({i,name:a.n,total:active.value?rows.value.filter(r=>r.oi===i).length:a.c,values:active.value?(matrixBy.value==='field'?data.fields:data.types).map((_,j)=>rows.value.filter(r=>r.oi===i&&(matrixBy.value==='field'?r.fi:r.ti)===j).length):matrixBy.value==='field'?a.d:a.t})).filter(a=>!active.value||a.total).sort((a,b)=>b.total-a.total))
const cohortMatrix = computed(() => data.cohortTotals.map((entry,i) => {
 const filtered = rows.value.filter(row=>row.ci===i)
 const values = active.value ? [filtered.length,...data.types.map((_,j)=>filtered.filter(r=>r.ti===j).length),...data.fields.map((_,j)=>filtered.filter(r=>r.fi===j).length)] : entry.v
 return {name:entry.n,index:i,values}
}).filter(row=>!active.value||row.values[0]))
function select(key:string,i:number){const target=key==='type'?type:key==='field'?field:cohort;target.value=target.value===String(i)?'':String(i)}
function clear(){query.value=agency.value=type.value=field.value=cohort.value=linkage.value=''}
function download(){
 if(matrix.value && matrixGroup.value==='cohort') {
   saveCSV('Aholi_toifalari_matritsasi.csv',[['Aholi toifasi','Jami',...data.types.map(latin),...data.fields.map(latin)],...cohortMatrix.value.map(row=>[latin(row.name),...row.values])]);return
 }
 if(matrix.value) {
   saveCSV('Idoralar_matritsasi.csv',[['Mas’ul idora','Jami',...(matrixBy.value==='field'?data.fields:data.types).map(latin)],...matrixRows.value.map(row=>[latin(row.name),row.total,...row.values])]);return
 }
 saveCSV('Choralar_reyestri.csv',[['ID','Chora','Idora','Tur','Yo‘nalish','Toifa','Huquqiy asos'],...rows.value.map(x=>[x.id,latin(x.n),latin(x.o),latin(data.types[x.ti]),latin(data.fields[x.fi]),latin(x.cn),latin(x.b)])])}
</script>
<template><div class="registry-view np-section-stack"><Teleport defer to="#support-filter-fields">
<label>{{ benefitText('Excel bilan moslik') }}<select v-model="linkage"><option value="">{{ benefitText('Barcha yozuvlar') }}</option><option value="linked">{{ benefitText('Bog‘langan') }}</option><option value="unlinked">{{ benefitText('Tekshiriladigan') }}</option></select></label>
<label>{{ benefitText("Chora turi") }}<select v-model="type"><option value="">{{ benefitText("Barchasi") }}</option><option v-for="(n,i) in data.types" :value="String(i)" :key="i">{{ benefitText(n) }}</option></select></label>
<label>{{ benefitText("Yo‘nalish") }}<select v-model="field"><option value="">{{ benefitText("Barchasi") }}</option><option v-for="(n,i) in data.fields" :value="String(i)" :key="i">{{ benefitText(n) }}</option></select></label>
<label>{{ benefitText("Aholi toifasi") }}<select v-model="cohort"><option value="">{{ benefitText("Barchasi") }}</option><option v-for="(n,i) in data.cohorts" :value="String(i)" :key="i">{{ benefitText(n) }}</option></select></label></Teleport><div class="section-heading"><div><p>{{ benefitText("37 idora · 3 tur · 6 yo‘nalish · 8 aholi toifasi") }}</p></div><button class="np-button" @click="download"><Download :size="14"/>{{ benefitText("Eksport") }}</button></div><div class="registry-summary"><div><b>{{ num(data.registryTotal) }}</b><span>{{ benefitText("Manbadagi yig‘ma choralar") }}</span></div><div><b>{{ num(data.registry.length) }}</b><span>{{ benefitText("Idoralar kesimidagi yozuvlar") }}</span></div><div><b>{{ num(rows.length) }}</b><span>{{ benefitText("Joriy tanlovdagi yozuvlar") }}</span></div><div><b>{{ benefitText(new Set(rows.map(x=>x.oi)).size) }}</b><span>{{ benefitText("Tanlovdagi idoralar") }}</span></div></div><div class="registry-dimensions"><section v-for="dimension in dimensions" :key="dimension.key" class="np-card"><h3>{{ benefitText(dimension.title) }}</h3><button v-for="(name,i) in dimension.names" :key="name" class="dimension-row" :class="{selected:dimension.selected===String(i)}" @click="select(dimension.key,i)"><span>{{ benefitText(name) }}</span><b>{{ benefitText(dimension.values[i]) }}</b><i :style="{width:Math.max(2,(dimension.values[i]??0)/Math.max(...dimension.values,1)*100)+'%',background:colors[i%colors.length]}"/></button></section></div><div class="np-card"><div class="np-toolbar"><Teleport defer to="#support-filter-fields"><label class="np-search"><Search :size="15"/><input v-model="query" :placeholder="benefitText('Chora, idora yoki huquqiy asos bo‘yicha qidirish')" :aria-label="benefitText('Reyestr qidiruvi')"/></label></Teleport><Teleport defer to="#support-filter-fields"><select v-model="agency" :aria-label="benefitText('Reyestr idorasi')"><option value="">{{ benefitText("Barcha 37 idora") }}</option><option v-for="(item,i) in data.agencies" :key="i" :value="String(i)">{{ benefitText(item.n) }}</option></select></Teleport><button v-if="active" class="np-button" @click="clear"><X :size="14"/>{{ benefitText("Tozalash") }}</button><div class="np-segment"><button :class="{active:!matrix}" @click="matrix=false"><Rows3 :size="14"/>{{ benefitText("Ro‘yxat") }}</button><button :class="{active:matrix}" @click="matrix=true"><Table2 :size="14"/>{{ benefitText("Matritsa") }}</button></div></div><template v-if="matrix"><div class="np-toolbar"><Teleport defer to="#support-filter-fields"><label>{{ benefitText("Matritsa qatorlari") }}<select v-model="matrixGroup"><option value="agency">{{ benefitText("Idoralar") }}</option><option value="cohort">{{ benefitText("Aholi toifalari") }}</option></select></label><select v-if="matrixGroup==='agency'" v-model="matrixBy" :aria-label="benefitText('Matritsa kesimi')"><option value="field">{{ benefitText("Yo‘nalishlar") }}</option><option value="type">{{ benefitText("Chora turlari") }}</option></select></Teleport></div><div v-if="matrixGroup==='cohort'" class="np-table-wrap"><table class="np-table"><thead><tr><th>{{ benefitText("Aholi toifasi") }}</th><th>{{ benefitText("Jami") }}</th><th v-for="name in [...data.types,...data.fields]" :key="name">{{ benefitText(name) }}</th></tr></thead><tbody><tr v-for="row in cohortMatrix" :key="row.index"><td><button class="text-button" @click="cohort=String(row.index);matrix=false">{{ benefitText(row.name) }}</button></td><td v-for="(value,j) in row.values" :key="j">{{ num(value) }}</td></tr></tbody></table></div><div v-else class="np-table-wrap"><table class="np-table"><thead><tr><th>{{ benefitText("Mas’ul idora") }}</th><th>{{ benefitText("Jami") }}</th><th v-for="name in matrixBy==='field'?data.fields:data.types" :key="name">{{ benefitText(name) }}</th></tr></thead><tbody><tr v-for="row in matrixRows" :key="row.i"><td><button class="text-button" @click="agency=String(row.i);matrix=false">{{ benefitText(row.name) }} <ArrowUpRight :size="13"/></button></td><td><b>{{ benefitText(row.total) }}</b></td><td v-for="(value,i) in row.values" :key="i"><span class="matrix-cell" :style="{background:`color-mix(in srgb, ${colors[i%colors.length]} ${Math.min(value*2,70)}%, transparent)`}">{{ benefitText(value||'—') }}</span></td></tr></tbody></table></div></template><template v-else><div class="np-table-wrap"><table class="np-table"><thead><tr><th>{{ benefitText("Chora nomi") }}</th><th>{{ benefitText("Mas’ul idora") }}</th><th>{{ benefitText("Tur / yo‘nalish") }}</th><th>{{ benefitText("Aholi toifasi") }}</th><th></th></tr></thead><tbody><tr v-for="row in rows.slice((page-1)*20,page*20)" :key="row.id"><td><button class="text-button" @click="emit('open',row)">{{ benefitText(row.n) }}</button><small>{{ benefitText(row.b) }}</small></td><td>{{ benefitText(row.o) }}</td><td><span class="np-tag blue">{{ benefitText(data.types[row.ti]) }}</span><small>{{ benefitText(data.fields[row.fi]) }}</small></td><td>{{ benefitText(row.cn) }}</td><td><button class="icon-button" :aria-label="benefitText(benefitText(row.n)+' kartasi')" @click="emit('open',row)"><ArrowUpRight :size="16"/></button></td></tr><tr v-if="!rows.length"><td colspan="5" class="np-empty">{{ benefitText("Tanlangan mezonlar bo‘yicha chora topilmadi. ") }}<button @click="clear">{{ benefitText("Filtrlarni tozalash") }}</button></td></tr></tbody></table></div><div class="np-pagination"><span>{{ benefitText(rows.length?((page-1)*20+1):0) }}–{{ Math.min(page*20,rows.length) }} / {{ num(rows.length) }}{{ benefitText(" yozuv") }}</span><button :disabled="page===1" :aria-label="benefitText('Oldingi sahifa')" @click="page--"><ChevronLeft :size="16"/></button><b>{{ benefitText(page) }} / {{ benefitText(pages) }}</b><button :disabled="page>=pages" :aria-label="benefitText('Keyingi sahifa')" @click="page++"><ChevronRight :size="16"/></button></div></template><details class="np-note"><summary>{{ benefitText("577 va 613 ko‘rsatkichlari haqida") }}</summary><p>{{ benefitText("Manbada 577 — yig‘ma jadvaldagi chora soni. Batafsil reyestrda 613 ta idora-chora yozuvi mavjud. Bir chorani bir necha idora ko‘rsatishi mumkin. Filtrlanganda batafsil yozuvlar sanaladi.") }}</p></details></div></div></template>
<style scoped>.registry-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-bottom:20px}.registry-summary>div{padding:18px 22px;background:var(--card);border:1px solid var(--border);border-radius:11px;display:grid;gap:5px}.registry-summary b{font-size:27px;color:#345cba}.registry-summary span{font-size:11px;color:var(--muted-foreground)}.registry-dimensions{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:20px}.dimension-row{position:relative;width:100%;display:flex;justify-content:space-between;gap:9px;text-align:left;font-size:11px;padding:11px 0 9px;border-bottom:2px solid var(--muted);margin:2px 0}.dimension-row span{color:var(--muted-foreground)}.dimension-row b{color:var(--foreground)}.dimension-row i{position:absolute;bottom:-2px;left:0;height:2px;border-radius:6px;transition:width .5s}.dimension-row.selected{background:#edf3ff;padding-left:8px;padding-right:8px}.matrix-cell{display:block;text-align:center;border-radius:4px;padding:5px}.np-table td:first-child{min-width:270px}.np-table td:nth-child(2){min-width:160px}@media(max-width:900px){.registry-dimensions{grid-template-columns:1fr}.registry-summary{grid-template-columns:1fr 1fr}}</style>
